/** TDesign 原生组件（miniprogram_dist）在 JSX 中的全局类型声明 */
declare namespace JSX {
  interface IntrinsicElements {
    't-chat-message': any;
    't-toast': any;
    't-dialog': any;
    't-skeleton': any;
    't-loading': any;
    't-tab-bar': any;
    't-tab-bar-item': any;
    't-popup': any;
    't-switch': any;
    't-slider': any;
    't-date-time-picker': any;
    't-picker': any;
    't-picker-item': any;
    't-notice-bar': any;
    't-image-viewer': any;
    't-empty': any;
  }
}
